/**
 * @claude-flow/browser - Agent Browser Adapter Tests
 */

import { describe, it, expect, beforeEach, vi, afterEach } from 'vitest';
import { AgentBrowserAdapter } from '../src/infrastructure/agent-browser-adapter.js';
import { execFileSync } from 'child_process';

vi.mock('child_process', () => ({
  execSync: vi.fn(),
  execFileSync: vi.fn(),
  spawn: vi.fn(),
}));

const mockExecSync = vi.mocked(execFileSync);

describe('AgentBrowserAdapter', () => {
  let adapter: AgentBrowserAdapter;

  beforeEach(() => {
    adapter = new AgentBrowserAdapter({
      session: 'test-session',
      timeout: 5000,
    });
    vi.clearAllMocks();
  });

  afterEach(() => {
    vi.clearAllMocks();
  });

  describe('constructor', () => {
    it('should create adapter with default options', () => {
      const defaultAdapter = new AgentBrowserAdapter();
      expect(defaultAdapter).toBeInstanceOf(AgentBrowserAdapter);
    });

    it('should create adapter with custom options', () => {
      const customAdapter = new AgentBrowserAdapter({
        session: 'custom',
        timeout: 10000,
        headless: false,
        debug: true,
      });
      expect(customAdapter).toBeInstanceOf(AgentBrowserAdapter);
    });
  });

  describe('navigation', () => {
    it('should open a URL', async () => {
      mockExecSync.mockReturnValue(JSON.stringify({
        success: true,
        data: { url: 'https://example.com' },
      }));

      const result = await adapter.open({ url: 'https://example.com' });

      expect(result.success).toBe(true);
      expect(mockExecSync).toHaveBeenCalled();
      const callArgs = (mockExecSync.mock.calls[0][1] as string[]).join(' ');
      expect(callArgs).toContain('open');
      expect(callArgs).toContain('https://example.com');
    });

    it('should go back', async () => {
      mockExecSync.mockReturnValue(JSON.stringify({ success: true }));

      const result = await adapter.back();

      expect(result.success).toBe(true);
      expect(mockExecSync).toHaveBeenCalled();
    });

    it('should go forward', async () => {
      mockExecSync.mockReturnValue(JSON.stringify({ success: true }));

      const result = await adapter.forward();

      expect(result.success).toBe(true);
    });

    it('should reload', async () => {
      mockExecSync.mockReturnValue(JSON.stringify({ success: true }));

      const result = await adapter.reload();

      expect(result.success).toBe(true);
    });

    it('should close', async () => {
      mockExecSync.mockReturnValue(JSON.stringify({ success: true }));

      const result = await adapter.close();

      expect(result.success).toBe(true);
    });
  });

  describe('interaction', () => {
    it('should click an element', async () => {
      mockExecSync.mockReturnValue(JSON.stringify({
        success: true,
        data: { clicked: true },
      }));

      const result = await adapter.click({ target: '@e1' });

      expect(result.success).toBe(true);
      const callArgs = (mockExecSync.mock.calls[0][1] as string[]).join(' ');
      expect(callArgs).toContain('click');
      expect(callArgs).toContain('@e1');
    });

    it('should fill an input', async () => {
      mockExecSync.mockReturnValue(JSON.stringify({
        success: true,
        data: { filled: true },
      }));

      const result = await adapter.fill({ target: '@e1', value: 'test' });

      expect(result.success).toBe(true);
      const callArgs = (mockExecSync.mock.calls[0][1] as string[]).join(' ');
      expect(callArgs).toContain('fill');
    });

    it('should type text', async () => {
      mockExecSync.mockReturnValue(JSON.stringify({ success: true }));

      const result = await adapter.type({ target: '@e1', text: 'hello' });

      expect(result.success).toBe(true);
      const callArgs = (mockExecSync.mock.calls[0][1] as string[]).join(' ');
      expect(callArgs).toContain('type');
    });

    it('should press a key', async () => {
      mockExecSync.mockReturnValue(JSON.stringify({ success: true }));

      const result = await adapter.press('Enter');

      expect(result.success).toBe(true);
      const callArgs = (mockExecSync.mock.calls[0][1] as string[]).join(' ');
      expect(callArgs).toContain('press');
      expect(callArgs).toContain('Enter');
    });

    it('should hover an element', async () => {
      mockExecSync.mockReturnValue(JSON.stringify({ success: true }));

      const result = await adapter.hover('@e1');

      expect(result.success).toBe(true);
    });

    it('should scroll', async () => {
      mockExecSync.mockReturnValue(JSON.stringify({ success: true }));

      const result = await adapter.scroll('down', 500);

      expect(result.success).toBe(true);
    });
  });

  describe('information retrieval', () => {
    it('should get text', async () => {
      mockExecSync.mockReturnValue(JSON.stringify({
        success: true,
        data: 'Element text',
      }));

      const result = await adapter.getText('@e1');

      expect(result.success).toBe(true);
      expect(result.data).toBe('Element text');
    });

    it('should get title', async () => {
      mockExecSync.mockReturnValue(JSON.stringify({
        success: true,
        data: 'Page Title',
      }));

      const result = await adapter.getTitle();

      expect(result.success).toBe(true);
    });

    it('should get URL', async () => {
      mockExecSync.mockReturnValue(JSON.stringify({
        success: true,
        data: 'https://example.com',
      }));

      const result = await adapter.getUrl();

      expect(result.success).toBe(true);
    });
  });

  describe('state checks', () => {
    it('should check visibility', async () => {
      mockExecSync.mockReturnValue(JSON.stringify({
        success: true,
        data: true,
      }));

      const result = await adapter.isVisible('@e1');

      expect(result.success).toBe(true);
      expect(result.data).toBe(true);
    });

    it('should check if enabled', async () => {
      mockExecSync.mockReturnValue(JSON.stringify({
        success: true,
        data: true,
      }));

      const result = await adapter.isEnabled('@e1');

      expect(result.success).toBe(true);
    });
  });

  describe('snapshot', () => {
    it('should take a snapshot', async () => {
      mockExecSync.mockReturnValue(JSON.stringify({
        success: true,
        data: {
          tree: { role: 'document', children: [] },
          refs: {},
          url: 'https://example.com',
          title: 'Test',
        },
      }));

      const result = await adapter.snapshot();

      expect(result.success).toBe(true);
      expect(result.data).toBeDefined();
    });

    it('should take interactive snapshot', async () => {
      mockExecSync.mockReturnValue(JSON.stringify({
        success: true,
        data: { tree: { role: 'document' } },
      }));

      const result = await adapter.snapshot({ interactive: true });

      expect(result.success).toBe(true);
      const callArgs = (mockExecSync.mock.calls[0][1] as string[]).join(' ');
      expect(callArgs).toContain('-i');
    });

    it('should take compact snapshot', async () => {
      mockExecSync.mockReturnValue(JSON.stringify({ success: true }));

      const result = await adapter.snapshot({ compact: true });

      const callArgs = (mockExecSync.mock.calls[0][1] as string[]).join(' ');
      expect(callArgs).toContain('-c');
    });
  });

  describe('screenshot', () => {
    it('should take a screenshot', async () => {
      mockExecSync.mockReturnValue(JSON.stringify({
        success: true,
        data: 'base64encodedimage',
      }));

      const result = await adapter.screenshot();

      expect(result.success).toBe(true);
    });

    it('should take full page screenshot', async () => {
      mockExecSync.mockReturnValue(JSON.stringify({ success: true }));

      const result = await adapter.screenshot({ fullPage: true });

      const callArgs = (mockExecSync.mock.calls[0][1] as string[]).join(' ');
      expect(callArgs).toContain('--full');
    });
  });

  describe('wait', () => {
    it('should wait for selector', async () => {
      mockExecSync.mockReturnValue(JSON.stringify({ success: true }));

      const result = await adapter.wait({ selector: '#element' });

      expect(result.success).toBe(true);
    });

    it('should wait for timeout', async () => {
      mockExecSync.mockReturnValue(JSON.stringify({ success: true }));

      const result = await adapter.wait({ timeout: 1000 });

      expect(result.success).toBe(true);
    });
  });

  describe('error handling', () => {
    it('should handle command failure', async () => {
      mockExecSync.mockImplementation(() => {
        throw new Error('Command failed');
      });

      const result = await adapter.open({ url: 'https://example.com' });

      expect(result.success).toBe(false);
      expect(result.error).toContain('Command failed');
    });

    it('should handle invalid JSON response', async () => {
      mockExecSync.mockReturnValue('invalid json');

      const result = await adapter.open({ url: 'https://example.com' });

      // Should fall back to raw string
      expect(result.success).toBe(true);
    });
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { xFederationTools } from '../src/mcp-tools/x-federation-tools.js';
import { seraphinaTools } from '../src/mcp-tools/seraphina-tools.js';

const call = (name: string, args: Record<string, unknown> = {}) =>
  [...xFederationTools, ...seraphinaTools].find(t => t.name === name)!.handler(args, {} as any);
const writes = ['x_federation_publish', 'x_federation_invite_mint', 'x_federation_admit'];
const reads = ['x_federation_sync', 'x_federation_roster', 'x_federation_claims', 'x_federation_registry'];

describe('MCP service destinations are operator-controlled', () => {
  beforeEach(() => {
    vi.stubEnv('RUFLO_X_ADMIN_TOKEN', 'SYNTHETIC-ADMIN-CANARY');
    vi.stubEnv('SERAPHINA_METALLM_KEY', 'SYNTHETIC-LLM-CANARY');
    vi.stubEnv('RUFLO_X_GATEWAY_URL', 'https://trusted-gateway.example');
    vi.stubEnv('SERAPHINA_METALLM_URL', 'https://trusted-llm.example');
    vi.stubGlobal('fetch', vi.fn(async (url: string, init: RequestInit) => {
      const body = JSON.parse(String(init.body));
      if (url.endsWith('/v1/messages')) return Response.json({ content: [{ text: '{"guidance":"safe","proposals":[],"risks":[]}' }] });
      const result = body.method === 'resources/read'
        ? { contents: [{ text: '{}' }] }
        : { content: [{ text: '{}' }] };
      return Response.json({ jsonrpc: '2.0', id: 1, result });
    }));
  });
  afterEach(() => { vi.unstubAllGlobals(); vi.unstubAllEnvs(); });

  it.each([...writes, ...reads])('%s rejects an attacker URL before any request', async name => {
    await expect(call(name, { gatewayUrl: 'https://attacker.example', msgType: 'Status', payload: {}, pubkey: 'a'.repeat(64) }))
      .rejects.toThrow(/configured/);
    expect(fetch).not.toHaveBeenCalled();
  });
  it.each(['metaLlmUrl', 'gatewayUrl'])('Seraphina rejects %s before reading swarm data or sending its key', async field => {
    await expect(call('seraphina_guidance', { goal: 'test', [field]: 'https://attacker.example' })).rejects.toThrow(/configured/);
    expect(fetch).not.toHaveBeenCalled();
  });
  it.each(['http://127.0.0.1:19999', 'http://169.254.169.254', 'file:///etc/passwd', 'https://trusted-gateway.example@attacker.example', 'https://trusted-gateway.example:444', 'https://trusted-gateway.example/other', 'https://trusted-gateway.example?x=1', 'https://trusted-gateway.example#x', {}, 0, false])('rejects hostile or malformed override %j', async gatewayUrl => {
    await expect(call('x_federation_publish', { gatewayUrl, msgType: 'Status', payload: {} })).rejects.toThrow();
    expect(fetch).not.toHaveBeenCalled();
  });
  it.each(writes)('%s sends its canary only to the configured gateway and disables redirects', async name => {
    await call(name, { gatewayUrl: 'https://trusted-gateway.example/', msgType: 'Status', payload: {}, pubkey: 'a'.repeat(64) });
    expect(fetch).toHaveBeenCalledWith('https://trusted-gateway.example/mcp', expect.objectContaining({ redirect: 'error' }));
    const init = vi.mocked(fetch).mock.calls[0][1]!;
    expect(JSON.parse(String(init.body)).params.arguments.adminToken).toBe('SYNTHETIC-ADMIN-CANARY');
    expect(JSON.parse(String(init.body)).params.arguments.gatewayUrl).toBeUndefined();
  });
  it('Seraphina uses configured services, retains tier selection and disables redirects everywhere', async () => {
    await call('seraphina_guidance', { goal: 'test', tier: 'cognitum-high', metaLlmUrl: 'https://trusted-llm.example/', gatewayUrl: 'https://trusted-gateway.example' });
    expect(fetch).toHaveBeenCalledTimes(4);
    for (const [, init] of vi.mocked(fetch).mock.calls) expect(init?.redirect).toBe('error');
    expect(fetch).toHaveBeenLastCalledWith('https://trusted-llm.example/v1/messages', expect.objectContaining({ headers: expect.objectContaining({ 'x-api-key': 'SYNTHETIC-LLM-CANARY' }) }));
    expect(JSON.parse(String(vi.mocked(fetch).mock.calls.at(-1)![1]!.body)).model).toBe('cognitum-high');
  });
  it.each(['http://public.example', 'http://localhost.attacker.example', 'http://127.0.0.1.nip.io', 'http://10.0.0.1', 'file:///tmp/test', 'https://user:pass@trusted.example', 'https://trusted.example?x=1', 'https://trusted.example#x'])('rejects unsafe operator configuration %s', async value => {
    vi.stubEnv('RUFLO_X_GATEWAY_URL', value);
    await expect(call('x_federation_sync')).rejects.toThrow();
    expect(fetch).not.toHaveBeenCalled();
  });
  it.each([undefined, null, ''])('an absent override (%j) asserts nothing: the configured gateway is used', async gatewayUrl => {
    await call('x_federation_sync', { gatewayUrl });
    expect(fetch).toHaveBeenCalledWith('https://trusted-gateway.example/mcp', expect.objectContaining({ redirect: 'error' }));
  });
  it('operator config may name a loopback HTTP service; a matching assertion passes, another port does not', async () => {
    vi.stubEnv('RUFLO_X_GATEWAY_URL', 'http://localhost:8080');
    await call('x_federation_sync', { gatewayUrl: 'http://localhost:8080/' });
    expect(fetch).toHaveBeenCalledWith('http://localhost:8080/mcp', expect.anything());
    vi.mocked(fetch).mockClear();
    await expect(call('x_federation_publish', { gatewayUrl: 'http://localhost:9999', msgType: 'Status', payload: {} })).rejects.toThrow(/must match/);
    expect(fetch).not.toHaveBeenCalled();
  });
  it('validates the LLM configuration before any gateway fetch', async () => {
    vi.stubEnv('SERAPHINA_METALLM_URL', 'http://public.example');
    await expect(call('seraphina_guidance', { goal: 'test' })).rejects.toThrow();
    expect(fetch).not.toHaveBeenCalled();
  });
});

import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { StreamableHTTPError } from "@modelcontextprotocol/sdk/client/streamableHttp.js";

// We mock the MCP SDK transports + Client so we can drive the connection
// outcomes deterministically. The point of these tests is to verify that
// clientPool.ts:
//   1. Skips the SSE fallback when the first transport returns 4xx/5xx (e.g. 429)
//      because retrying via SSE will hit the same upstream and produce the
//      same rate-limit response.
//   2. Surfaces a typed McpRateLimitedError on 429 with retryAfterMs derived
//      from the upstream Retry-After header when present.
//   3. Memoizes the failure for a cooldown window so subsequent getClient
//      calls don't pound the upstream.
//   4. Still falls back to SSE for transport-level / network errors that
//      have no HTTP status (the "Streamable HTTP server is not running" path).

const httpConnectMock = vi.fn();
const sseConnectMock = vi.fn();

vi.mock("@modelcontextprotocol/sdk/client", () => {
	class MockClient {
		private nextTransportIsHttp = true;
		async connect(transport: unknown) {
			// The transport instances are tagged below in the streamableHttp/sse mocks.
			const isHttp = (transport as { __kind?: string }).__kind === "http";
			if (isHttp) {
				return httpConnectMock();
			}
			return sseConnectMock();
		}
		async close() {}
		async callTool() {
			return { content: [] };
		}
	}
	return { Client: MockClient };
});

vi.mock("@modelcontextprotocol/sdk/client/streamableHttp.js", () => {
	class StreamableHTTPError extends Error {
		code: number;
		constructor(code: number, message: string) {
			super(`Streamable HTTP error: ${message}`);
			this.code = code;
			this.name = "StreamableHTTPError";
		}
	}
	class StreamableHTTPClientTransport {
		__kind = "http";
		constructor(_url: URL, _opts: unknown) {}
	}
	return { StreamableHTTPError, StreamableHTTPClientTransport };
});

vi.mock("@modelcontextprotocol/sdk/client/sse.js", () => {
	class SSEClientTransport {
		__kind = "sse";
		constructor(_url: URL, _opts: unknown) {}
	}
	return { SSEClientTransport };
});

// Import AFTER vi.mock declarations.
import { getClient, drainPool, McpRateLimitedError } from "./clientPool";

const server = { name: "test-server", url: "https://example.test/mcp", headers: {} };

describe("clientPool — rate-limit and HTTP error handling", () => {
	beforeEach(async () => {
		await drainPool();
		httpConnectMock.mockReset();
		sseConnectMock.mockReset();
	});

	afterEach(async () => {
		await drainPool();
	});

	it("skips SSE fallback on 429 and throws McpRateLimitedError", async () => {
		httpConnectMock.mockRejectedValue(
			new StreamableHTTPError(
				429,
				"Error POSTing to endpoint: Rate exceeded. Retry-After: 7"
			)
		);

		await expect(getClient(server)).rejects.toBeInstanceOf(McpRateLimitedError);
		// Critical: SSE was NOT attempted — would just hit the same upstream.
		expect(sseConnectMock).not.toHaveBeenCalled();
		expect(httpConnectMock).toHaveBeenCalledTimes(1);
	});

	it("honors Retry-After when present in the error message", async () => {
		httpConnectMock.mockRejectedValue(
			new StreamableHTTPError(
				429,
				"Error POSTing to endpoint: Rate exceeded. Retry-After: 12"
			)
		);

		try {
			await getClient(server);
			throw new Error("should have thrown");
		} catch (err) {
			expect(err).toBeInstanceOf(McpRateLimitedError);
			expect((err as McpRateLimitedError).retryAfterMs).toBe(12_000);
			expect((err as McpRateLimitedError).status).toBe(429);
			expect((err as McpRateLimitedError).serverName).toBe("test-server");
		}
	});

	it("memoizes the 429 failure and skips network on subsequent calls during cooldown", async () => {
		httpConnectMock.mockRejectedValue(
			new StreamableHTTPError(429, "Error POSTing to endpoint: Rate exceeded. Retry-After: 5")
		);

		await expect(getClient(server)).rejects.toBeInstanceOf(McpRateLimitedError);
		// Second call within the cooldown window: must NOT touch the upstream again.
		await expect(getClient(server)).rejects.toBeInstanceOf(McpRateLimitedError);
		expect(httpConnectMock).toHaveBeenCalledTimes(1);
		expect(sseConnectMock).not.toHaveBeenCalled();
	});

	it("skips SSE fallback on 4xx (e.g. 401)", async () => {
		httpConnectMock.mockRejectedValue(
			new StreamableHTTPError(401, "Unauthorized")
		);
		await expect(getClient(server)).rejects.toThrow(/HTTP 401/);
		expect(sseConnectMock).not.toHaveBeenCalled();
	});

	it("skips SSE fallback on 5xx (e.g. 503)", async () => {
		httpConnectMock.mockRejectedValue(
			new StreamableHTTPError(503, "Service Unavailable")
		);
		await expect(getClient(server)).rejects.toThrow(/HTTP 503/);
		expect(sseConnectMock).not.toHaveBeenCalled();
	});

	it("falls back to SSE on transport-level / network errors with no HTTP status", async () => {
		httpConnectMock.mockRejectedValue(new Error("ECONNREFUSED"));
		sseConnectMock.mockResolvedValue(undefined);

		const client = await getClient(server);
		expect(client).toBeDefined();
		expect(httpConnectMock).toHaveBeenCalledTimes(1);
		expect(sseConnectMock).toHaveBeenCalledTimes(1);
	});

	it("falls back to SSE on 408 Request Timeout (recoverable)", async () => {
		httpConnectMock.mockRejectedValue(
			new StreamableHTTPError(408, "Request Timeout")
		);
		sseConnectMock.mockResolvedValue(undefined);

		const client = await getClient(server);
		expect(client).toBeDefined();
		expect(sseConnectMock).toHaveBeenCalledTimes(1);
	});

	it("surfaces 429 even when the SSE fallback also reports 429", async () => {
		httpConnectMock.mockRejectedValue(new Error("transport mismatch")); // forces SSE attempt
		sseConnectMock.mockRejectedValue(
			new Error("SSE error: Non-200 status code (429)")
		);

		try {
			await getClient(server);
			throw new Error("should have thrown");
		} catch (err) {
			expect(err).toBeInstanceOf(McpRateLimitedError);
			expect((err as McpRateLimitedError).status).toBe(429);
		}
	});
});

